package net.koalastuff.koalacast.core.ui.icon

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Phosphor icons the app uses, as path data rather than as a dependency: the set
 * is small, the licence is MIT, and shipping the glyphs we actually draw keeps the
 * APK honest. Path data is copied verbatim from phosphor-icons/core (256x256 grid).
 *
 * Add an icon by pasting the `d` attribute of its SVG — do not redraw one by hand.
 */
private fun phosphor(name: String, pathData: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 256f,
        viewportHeight = 256f,
    ).addPath(
        pathData = addPathNodes(pathData),
        fill = SolidColor(Color.Black),
    ).build()

